MAX_IDS = 50
BATCH_TIMEOUT_MS = 300

def fetch_all(ids, batch_get_fn):
    ids = list(dict.fromkeys(ids))  # dedupe, keep order
    results = {}
    errors = {}
    for i in range(0, len(ids), MAX_IDS):
        chunk = ids[i:i + MAX_IDS]
        resp = batch_get_fn(chunk, timeout_ms=BATCH_TIMEOUT_MS)
        # resp: {"found": {id: val}, "retryable": {id: err}, "fatal": {id: err}}
        results.update(resp["found"])
        # retry ONLY retryable IDs, with backoff, not the whole chunk
        if resp["retryable"]:
            time.sleep(random.uniform(0.02, 0.1))
            retry = batch_get_fn(list(resp["retryable"]), timeout_ms=BATCH_TIMEOUT_MS)
            results.update(retry["found"])
            errors.update(retry["retryable"])
        errors.update(resp["fatal"])
    return results, errors

// POST /bundles:batchGet { "ids": [...] }
// Never fail the batch for one bad ID. Trade-off: bigger contract, safe retries.
public BatchResponse batchGet(BatchRequest req) {
    if (req.ids().size() > 50) throw status(413, "max 50 ids per batch");
    Map<String, Bundle> found = new HashMap<>();
    Map<String, String> retryable = new HashMap<>();
    Map<String, String> fatal = new HashMap<>();
    Map<String, List<String>> byShard = partition(req.ids());
    byShard.values().parallelStream().limit(10).forEach(shardIds -> {
        try {
            lookupWithDeadline(shardIds, 200, found, retryable, fatal);
        } catch (TimeoutException e) {
            shardIds.forEach(id -> retryable.put(id, "TIMEOUT"));
        }
    });
    return new BatchResponse(found, retryable, fatal);
}
